compiler implements

	select {
	case c <- v:
		... foo
	default:
		... bar
	}

as

	if selectnbsend(c, v) {
		... foo
	} else {
		... bar
	}

compiler implements

	select {
	case v, ok = <-c:
		... foo
	default:
		... bar
	}

as

	if selected, ok = selectnbrecv(&v, c); selected {
		... foo
	} else {
		... bar
	}
